        ll w = edges[i].w;
        ll du = dist[u];
        ll dv = dist[v];
        // The maximum shortest distance on this edge is max(du, dv) if the edge is long enough
        // but if the edge is long, the farthest point is where the distances from u and v are equal
        // Actually, the function f(x) = min(du + x, dv + (w - x)) is maximized when du + x = dv + w - x
        // => 2x = dv + w - du => x = (dv + w - du) / 2
        // The maximum value is (du + dv + w) / 2
        // But we need to consider the actual possible range 0 <= x <= w
        double best = (du + dv + w) / 2.0;
