        if (x < 0) x = 0;
        if (x > w) x = w;
        double val = du + x;
        if (val > dv + w - x) val = dv + w - x;
        // Actually val is exactly min(du + x, dv + w - x)
        // But we computed best as (du+dv+w)/2 which is the maximum possible if x is unconstrained
