#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

typedef struct Edge {
    int to;
    ll w;
    int next;
} Edge;

typedef struct Road {
    int u, v;
    ll w;
} Road;

typedef struct HeapNode {
    ll d;
    int v;
} HeapNode;

static void heap_push(HeapNode *heap, int *sz, ll d, int v) {
    int i = ++(*sz);
    heap[i].d = d;
    heap[i].v = v;
    while (i > 1) {
        int p = i >> 1;
        if (heap[p].d <= heap[i].d) break;
        HeapNode tmp = heap[p];
        heap[p] = heap[i];
        heap[i] = tmp;
        i = p;
    }
}

static HeapNode heap_pop(HeapNode *heap, int *sz) {
    HeapNode ret = heap[1];
    heap[1] = heap[(*sz)--];
    int i = 1;
    while (1) {
        int l = i << 1, r = l + 1, m = i;
        if (l <= *sz && heap[l].d < heap[m].d) m = l;
        if (r <= *sz && heap[r].d < heap[m].d) m = r;
        if (m == i) break;
        HeapNode tmp = heap[i];
        heap[i] = heap[m];
        heap[m] = tmp;
        i = m;
    }
    return ret;
}

int main(void) {
    int N, M, K;
    if (scanf("%d %d %d", &N, &M, &K) != 3) return 0;

    int *is_shop = (int *)calloc(N + 1, sizeof(int));
    for (int i = 0; i < K; i++) {
        int x;
        scanf("%d", &x);
        is_shop[x] = 1;
    }

    Edge *edges = (Edge *)malloc(sizeof(Edge) * (2 * M + 5));
    Road *roads = (Road *)malloc(sizeof(Road) * M);
    int *head = (int *)malloc(sizeof(int) * (N + 1));
    for (int i = 1; i <= N; i++) head[i] = -1;

    int ecnt = 0;
    for (int i = 0; i < M; i++) {
        int a, b;
        ll c;
        scanf("%d %d %lld", &a, &b, &c);
        roads[i].u = a;
        roads[i].v = b;
        roads[i].w = c;

        edges[ecnt].to = b;
        edges[ecnt].w = c;
        edges[ecnt].next = head[a];
        head[a] = ecnt++;

        edges[ecnt].to = a;
        edges[ecnt].w = c;
        edges[ecnt].next = head[b];
        head[b] = ecnt++;
    }

    const ll INF = (1LL << 62);
    ll *dist = (ll *)malloc(sizeof(ll) * (N + 1));
    for (int i = 1; i <= N; i++) dist[i] = INF;

    HeapNode *heap = (HeapNode *)malloc(sizeof(HeapNode) * (2 * M + N + 10));
    int hsz = 0;

    for (int i = 1; i <= N; i++) {
        if (is_shop[i]) {
            dist[i] = 0;
            heap_push(heap, &hsz, 0, i);
        }
    }

    while (hsz > 0) {
        HeapNode cur = heap_pop(heap, &hsz);
        ll d = cur.d;
        int v = cur.v;
        if (d != dist[v]) continue;
        for (int e = head[v]; e != -1; e = edges[e].next) {
            int to = edges[e].to;
            ll nd = d + edges[e].w;
            if (nd < dist[to]) {
                dist[to] = nd;
                heap_push(heap, &hsz, nd, to);
            }
        }
    }

    ll ans2 = 0; /* answer multiplied by 2 */

    for (int i = 1; i <= N; i++) {
        ll cand2 = 2 * dist[i];
        if (cand2 > ans2) ans2 = cand2;
    }

    for (int i = 0; i < M; i++) {
        int u = roads[i].u, v = roads[i].v;
        ll w = roads[i].w;
        ll du = dist[u], dv = dist[v];

        ll cand2;
        if (llabs(du - dv) >= w) {
            cand2 = 2 * (du < dv ? du + w : dv + w);
        } else {
            cand2 = du + dv + w;
        }
        if (cand2 > ans2) ans2 = cand2;
    }

    if (ans2 % 2 == 0) {
        printf("%lld\n", ans2 / 2);
    } else {
        printf("%lld.5\n", ans2 / 2);
    }

    free(is_shop);
    free(edges);
    free(roads);
    free(head);
    free(dist);
    free(heap);
    return 0;
}

