public class Main {

    static class Edge {
        int to;
        long len;
        Edge(int to, long len) {
            this.to = to;
            this.len = len;
        }
    }

    static class State implements Comparable<State> {
        int node;
        long dist;
        State(int node, long dist) {
            this.node = node;
            this.dist = dist;
        }
        public int compareTo(State other) {
            return Long.compare(this.dist, other.dist);
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().split(" ");
        int N = Integer.parseInt(parts[0]);
        int M = Integer.parseInt(parts[1]);
        int K = Integer.parseInt(parts[2]);

        boolean[] isMall = new boolean[N];
        StringTokenizer st = new StringTokenizer(br.readLine());
        for (int i = 0; i < K; i++) {
            int town = Integer.parseInt(st.nextToken()) - 1;
            isMall[town] = true;
        }

        List<Edge>[] graph = new ArrayList[N];
        for (int i = 0; i < N; i++) {
            graph[i] = new ArrayList<>();
        }

        long[] u = new long[M];
        long[] v = new long[M];
        long[] w = new long[M];

        for (int i = 0; i < M; i++) {
            parts = br.readLine().split(" ");
            int a = Integer.parseInt(parts[0]) - 1;
            int b = Integer.parseInt(parts[1]) - 1;
            long c = Long.parseLong(parts[2]);
            u[i] = a;
            v[i] = b;
            w[i] = c;
            graph[a].add(new Edge(b, c));
            graph[b].add(new Edge(a, c));
        }

        // Dijkstra from all malls
        long[] dist = new long[N];
        Arrays.fill(dist, Long.MAX_VALUE);
        PriorityQueue<State> pq = new PriorityQueue<>();

        for (int i = 0; i < N; i++) {
            if (isMall[i]) {
                dist[i] = 0;
                pq.offer(new State(i, 0));
            }
        }

        while (!pq.isEmpty()) {
            State cur = pq.poll();
            if (cur.dist != dist[cur.node]) continue;
            for (Edge e : graph[cur.node]) {
                long nd = cur.dist + e.len;
                if (nd < dist[e.to]) {
                    dist[e.to] = nd;
                    pq.offer(new State(e.to, nd));
                }
            }
        }

        // Now we need max over all points on edges of min distance to a mall
        // For each edge (a,b) with length w, the distance function along the edge
        // is a V-shaped function: f(x) = min(dist[a] + x, dist[b] + (w - x))
        // The maximum of this function occurs at the intersection point if it lies within [0,w]
        // The intersection is at x = (dist[b] - dist[a] + w) / 2
        // Value at intersection = (dist[a] + dist[b] + w) / 2
        // Also check endpoints.

        long answer = 0;
        for (int i = 0; i < N; i++) {
            answer = Math.max(answer, dist[i]);
        }

        for (int i = 0; i < M; i++) {
            int a = (int)u[i];
            int b = (int)v[i];
            long len = w[i];
            long da = dist[a];
            long db = dist[b];

            // Value at intersection point (if it lies within edge)
            // x = (db - da + len) / 2
            // Ensure numerator is even for exact midpoint; use double for maximum check
            double x = (db - da + len) / 2.0;
            if (x >= 0 && x <= len) {
                double val = da + x;
                long candidate = (long) Math.ceil(val - 1e-12); // avoid floating errors
                answer = Math.max(answer, candidate);
                // Also check floor might be needed but since we maximize, ceiling is enough
                // But to be safe, check both floor and ceil
                long floorVal = (long) Math.floor(val + 1e-12);
                long ceilVal = (long) Math.ceil(val - 1e-12);
                answer = Math.max(answer, floorVal);
                answer = Math.max(answer, ceilVal);
            }

            // Also check endpoints already considered via dist array
        }

        System.out.println(answer);
    }
}

