/*
 * JOI Kingdom - maximum distance from any point on roads to nearest shopping mall.
 *
 * Idea:
 * 1) Multi-source Dijkstra from all mall towns gives dist[v] = shortest distance
 *    from town v to any mall.
 * 2) For a road (u, v, w), consider a point x on it, at distance t from u.
 *    Its distance to nearest mall is:
 *        f(t) = min(dist[u] + t, dist[v] + (w - t))
 *    The maximum on this segment is attained where the two expressions meet,
 *    unless one dominates throughout. Therefore:
 *        max_on_edge = (dist[u] + dist[v] + w) / 2
 *    but not less than max(dist[u], dist[v])? Actually this formula already
 *    gives the correct maximum over the segment because if the meeting point
 *    lies outside the segment, the maximum is at an endpoint and equals the
 *    larger endpoint value. Integer-safe form:
 *        max_on_edge = max(dist[u], dist[v], floor/real expression)
 *    More directly and safely with doubled values:
 *        candidate2 = dist[u] + dist[v] + w   // equals 2 * formula
 *        edgeBest2 = max(2*dist[u], 2*dist[v], candidate2)
 *    But if candidate2 exceeds what is feasible when the intersection is outside
 *    segment? Let's derive properly:
 *
 *    Let a = dist[u], b = dist[v].
 *    f(t) = min(a+t, b+w-t), t in [0,w]
 *    The maximum is:
 *      if |a-b| <= w, then (a+b+w)/2
 *      else max(a, b) at an endpoint.
 *    So with doubled values:
 *      if |a-b| <= w: edgeBest2 = a+b+w
 *      else edgeBest2 = 2*max(a,b)
 *
 * 3) Answer is the maximum over all roads. Since the exact answer can be x.0 or x.5,
 *    print accordingly.
 */

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Edge {
        int to;
        long w;
        Edge(int to, long w) {
            this.to = to;
            this.w = w;
        }
    }

    static class Road {
        int u, v;
        long w;
        Road(int u, int v, long w) {
            this.u = u;
            this.v = v;
            this.w = w;
        }
    }

    static class Node implements Comparable<Node> {
        int v;
        long d;
        Node(int v, long d) {
            this.v = v;
            this.d = d;
        }
        public int compareTo(Node o) {
            return Long.compare(this.d, o.d);
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        int M = fs.nextInt();
        int K = fs.nextInt();

        List<Edge>[] g = new ArrayList[N];
        for (int i = 0; i < N; i++) g[i] = new ArrayList<>();
        Road[] roads = new Road[M];

        for (int i = 0; i < M; i++) {
            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;
            long c = fs.nextLong();
            g[a].add(new Edge(b, c));
            g[b].add(new Edge(a, c));
            roads[i] = new Road(a, b, c);
        }

        long INF = Long.MAX_VALUE / 4;
        long[] dist = new long[N];
        Arrays.fill(dist, INF);
        PriorityQueue<Node> pq = new PriorityQueue<>();

        for (int i = 0; i < K; i++) {
            int s = fs.nextInt() - 1;
            if (dist[s] > 0) {
                dist[s] = 0;
                pq.add(new Node(s, 0));
            }
        }

        while (!pq.isEmpty()) {
            Node cur = pq.poll();
            if (cur.d != dist[cur.v]) continue;
            for (Edge e : g[cur.v]) {
                long nd = cur.d + e.w;
                if (nd < dist[e.to]) {
                    dist[e.to] = nd;
                    pq.add(new Node(e.to, nd));
                }
            }
        }

        long ans2 = 0; // answer multiplied by 2

        for (Road r : roads) {
            long a = dist[r.u];
            long b = dist[r.v];
            long w = r.w;
            long best2;
            if (Math.abs(a - b) <= w) {
                best2 = a + b + w;
            } else {
                best2 = 2L * Math.max(a, b);
            }
            if (best2 > ans2) ans2 = best2;
        }

        StringBuilder out = new StringBuilder();
        if ((ans2 & 1L) == 0) {
            out.append(ans2 / 2).append('\n');
        } else {
            out.append(ans2 / 2).append(".5\n");
        }
        System.out.print(out.toString());
    }
}

