        int v;
        cin >> v;
        v--;
        isMall[v] = true;
        dist[v] = 0;
        pq.push({0, v});
    }

    for (int i = 0; i < M; i++) {
        int u, v;
        ll w;
        cin >> u >> v >> w;
        u--; v--;
        adj[u].push_back({v, w});
        adj[v].push_back({u, w});
    }

    // Dijkstra from all malls
    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
