            if (dist[v] > d + w) {
                dist[v] = d + w;
                pq.push({dist[v], v});
            }
        }
    }

    // Build graph of edges with their distances
    // For each edge (u,v,w), we have two distances from malls: dist[u] and dist[v]
    // We need the maximum possible shortest distance from any point on the edge
    // to the nearest mall.
    // Consider a point at distance x from u along the edge (0 <= x <= w).
    // Its distance to nearest mall is min(dist[u] + x, dist[v] + (w - x)).
    // The maximum of this over x is achieved when the two expressions are equal,
    // or at endpoints if they never meet.
    // Solve dist[u] + x = dist[v] + w - x => x = (dist[v] + w - dist[u]) / 2
    // If x is within [0, w], the max distance is dist[u] + x = (dist[u] + dist[v] + w) / 2
    // Otherwise, the max is max(dist[u], dist[v] + w) or max(dist[v], dist[u] + w)
    // Actually simpler: the function f(x) = min(dist[u] + x, dist[v] + w - x)
    // Its maximum is at the intersection point if within bounds, else at the closer endpoint.
    // The maximum value = max(min(dist[u] + w, dist[v]), min(dist[v] + w, dist[u]), (dist[u]+dist[v]+w)/2 if intersection in [0,w])
    // More directly: the maximum shortest distance on the edge is:
    // max( min(dist[u], dist[v] + w), min(dist[v], dist[u] + w), (dist[u] + dist[v] + w)/2 if intersection valid )
    // But the first two are covered by the third or endpoints.
    // Actually the maximum of f(x) over [0,w] is:
    // if |dist[u] - dist[v]| >= w: max(dist[u], dist[v]) + w? Let's derive properly.
    // f(x) = min(A + x, B + w - x) where A=dist[u], B=dist[v].
    // Intersection at x0 = (B + w - A)/2.
    // If x0 in [0,w], then max f = A + x0 = (A+B+w)/2.
    // Else if A <= B: then A + x <= B + w - x for all x? Actually if A <= B, then A + x <= B + w - x when x <= (B - A + w)/2.
    // If x0 < 0, then A + x < B + w - x for all x in [0,w], so f(x)=A+x, max at x=w => A+w.
    // If x0 > w, then f(x)=B+w-x, max at x=0 => B+w.
    // So max f = 
    // if A <= B: if A + w <= B? Actually condition x0<0 => B+w-A < 0 => B+w < A, but A<=B so impossible.
    // Let's do: x0 < 0 => B + w - A < 0 => B + w < A => A > B + w. Then max = A (at x=0? check: f(0)=min(A, B+w)=B+w, f(w)=min(A+w, B)=B, so max is B+w? Wait recalc.
    // Actually if A > B + w, then for all x, A + x > B + w - x? Let's test: A=10, B=1, w=2. Then f(0)=min(10,3)=3, f(2)=min(12,1)=1, max=3 = B+w.
    // So max = min(A, B+w) at x=0? That's B+w. So max = min(A, B+w) but since A > B+w, it's B+w.
    // Similarly if B > A + w, max = A+w.
    // So general formula: max f = max( min(A, B+w), min(B, A+w), (A+B+w)/2 if intersection valid ).
    // But min(A, B+w) and min(B, A+w) are just the endpoints contributions. The intersection point gives the middle.
    // Actually the maximum of f is exactly:
    // if abs(A - B) >= w: max(min(A, B+w), min(B, A+w)) = max(min(A, B+w), min(B, A+w))
    // else: (A+B+w)/2
    // But note that when abs(A-B) < w, the intersection point lies in (0,w), and (A+B+w)/2 >= both endpoint values? Let's check: (A+B+w)/2 >= A? => B+w >= A, true if A-B <= w. Similarly >= B? A+w >= B. So yes.
    // So we can compute for each edge.

    double ans = 0.0;
    for (int u = 0; u < N; u++) {
        for (auto [v, w] : adj[u]) {
            if (u > v) continue; // process each edge once
            ll A = dist[u], B = dist[v];
            // Consider all points on the edge including endpoints
            // The maximum shortest distance from a point on this edge to nearest mall
            double maxDist;
            if (abs(A - B) >= w) {
                maxDist = (double)max(min(A, B + w), min(B, A + w));
            } else {
