    priority_queue<pli, vector<pli>, greater<pli>> pq;

    for(int i = 0; i < K; i++){
        int t; cin >> t;
        dist[t] = 0;
        pq.push({0, t});
    }

    vector<vector<pair<int,ll>>> adj(N+1);
    vector<tuple<int,int,ll>> edges(M);

    for(int i = 0; i < M; i++){
        int u, v; ll w;
        cin >> u >> v >> w;
        adj[u].push_back({v, w});
        adj[v].push_back({u, w});
        edges[i] = {u, v, w};
    }

    while(!pq.empty()){
        auto [d, u] = pq.top(); pq.pop();
        if(d > dist[u]) continue;
        for(auto [v, w] : adj[u]){
            if(dist[u] + w < dist[v]){
                dist[v] = dist[u] + w;
                pq.push({dist[v], v});
            }
        }
    }

    ll ans = 0;
    for(auto [u, v, w] : edges){
        ll du = dist[u], dv = dist[v];
        ll val;
        // crossover x* = (dv + w - du)/2
        // Check if x* in [0, w]
        // 2*x* = dv + w - du
        ll num = dv + w - du; // = 2*x*
        if(num < 0){
            // x* < 0, max at x=0
            val = du;
        } else if(num > 2*w){
            // x* > w, max at x=w
            val = dv;
        } else {
            // val*2 = du + dv + w
            // We work with 2*val to avoid fractions
            val = -1; // handle separately
            ll val2 = du + dv + w; // this is 2*val
            // compare val2/2 with ans using *2
            ans = max(ans * 2, val2); // Hmm, need consistent units
            ans = (ans + 1) / 2; // round up? No...
            // Let me just use doubles or keep *2
            continue;
        }
        ans = max(ans, val);
    }

    cout << ans << endl;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll INF = (1LL << 62);

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M, K;
    cin >> N >> M >> K;

    vector<int> mall(K);
    for (int i = 0; i < K; i++) {
        cin >> mall[i];
        --mall[i];
    }

    vector<vector<pair<int,int>>> g(N);
    struct Edge {
        int u, v;
        ll w;
    };
    vector<Edge> edges;
    edges.reserve(M);

    for (int i = 0; i < M; i++) {
        int a, b, c;
        cin >> a >> b >> c;
        --a; --b;
        g[a].push_back({b, c});
        g[b].push_back({a, c});
        edges.push_back({a, b, c});
    }

    // Multi-source Dijkstra from all mall towns
    vector<ll> dist(N, INF);
    priority_queue<pair<ll,int>, vector<pair<ll,int>>, greater<pair<ll,int>>> pq;
    for (int s : mall) {
        dist[s] = 0;
        pq.push({0, s});
    }

    while (!pq.empty()) {
        auto [d, v] = pq.top();
        pq.pop();
        if (d != dist[v]) continue;
        for (auto [to, w] : g[v]) {
            if (dist[to] > d + w) {
                dist[to] = d + w;
                pq.push({dist[to], to});
            }
        }
    }

    // For a point x on edge (u,v,w), distance to nearest mall is:
    // min(dist[u] + x, dist[v] + (w - x))
    // The maximum on this edge is:
    // if |dist[u]-dist[v]| >= w -> min endpoint value
    // else -> (dist[u] + dist[v] + w) / 2
    //
    // To avoid floating point, compute answer * 2.
    ll ans2 = 0;
    for (auto &e : edges) {
        ll a = dist[e.u];
        ll b = dist[e.v];
        ll w = e.w;
        ll cand2;
        if (llabs(a - b) >= w) {
            cand2 = 2 * min(a, b) + 2 * w;
        } else {
            cand2 = a + b + w;
        }
        ans2 = max(ans2, cand2);
    }

    // Output can be integer or x.5
    if (ans2 % 2 == 0) {
        cout << (ans2 / 2) << '\n';
    } else {
        cout << (ans2 / 2) << ".5\n";
    }

    return 0;
}
